<?php
declare(strict_types=1);

function auth_shell(string $title, string $content): string {
    return '<!doctype html><html lang="ar" dir="rtl" class="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' . escape($title) . '</title><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;700;800&family=Aref+Ruqaa:wght@400;700&family=Reem+Kufi:wght@500;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="/styles/auth.css"><script src="/js/ui-language.js?v=2"></script></head><body><div class="basmala">بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ</div><button id="language-toggle" class="language-switch" type="button" onclick="AtharI18n.toggle()" aria-label="Switch to English" aria-pressed="false">English</button><div class="wrap"><div class="card">' . $content . '</div></div></body></html>';
}
function auth_error(string $message): string { return $message === '' ? '' : '<div class="err" role="alert">' . escape($message) . '</div>'; }
function auth_page(string $mode, string $error = ''): string {
    if ($mode === 'login') {
        $signup = (config()['allow_signup'] ?? true) ? '<a class="lnk" href="/signup">ليس لديك حساب؟ أنشئ حساباً</a>' : '';
        return auth_shell('تسجيل الدخول | أثر', '<div class="brand"><img src="/assets/media/c34b66558d65ceb69057.png" alt="أثر"></div><h1>مرحباً بك</h1><p class="sub">اكتب الاسم الذي أنشأت به حسابك للمتابعة</p>' . auth_error($error) . '<form method="post" action="/login"><label for="name">الاسم</label><input id="name" type="text" name="name" required autofocus autocomplete="username" maxlength="80" placeholder="اكتب اسمك"><label for="password">كلمة المرور</label><div class="input-wrap"><input id="password" type="password" name="pass" required autocomplete="current-password" maxlength="256" placeholder="أدخل كلمة المرور"><button type="button" class="toggle-pass" aria-label="إظهار كلمة المرور" onclick="const i=document.getElementById(\'password\');i.type=i.type===\'password\'?\'text\':\'password\';this.textContent=i.type===\'password\'?\'إظهار\':\'إخفاء\'">إظهار</button></div><button class="submit" type="submit">تسجيل الدخول</button></form>' . $signup . '<p class="foot">نبسّط العلم لنصنع المستقبل</p>');
    }
    $setup = $mode === 'setup';
    $title = $setup ? 'إنشاء حساب المدير' : 'إنشاء حساب جديد';
    $subtitle = $setup ? 'أول مرة؟ أنشئ حساب المدير باسمك وكلمة السر' : 'كل حساب له جدوله وطلابه الخاصين';
    return auth_shell($title, '<h1>' . $title . '</h1><p class="sub">' . $subtitle . '</p>' . auth_error($error) . '<form method="post" action="/' . $mode . '"><label for="name">الاسم</label><input id="name" type="text" name="name" required autofocus autocomplete="username" maxlength="80"><label for="phone">رقم الهاتف</label><input id="phone" type="text" name="phone" required inputmode="tel" autocomplete="tel" maxlength="40"><label for="password">كلمة السر (٦ أرقام)</label><input id="password" type="password" name="pass" required autocomplete="new-password" inputmode="numeric" pattern="[0-9٠-٩]{6}" minlength="6" maxlength="6"><label for="password-confirm">تأكيد كلمة السر</label><input id="password-confirm" type="password" name="pass2" required autocomplete="new-password" inputmode="numeric" pattern="[0-9٠-٩]{6}" minlength="6" maxlength="6"><button class="submit" type="submit">إنشاء الحساب والدخول</button></form>' . ($setup ? '' : '<a class="lnk" href="/login">عندي حساب بالفعل - تسجيل الدخول</a>'));
}

function admin_page(array $admin, string $notice = ''): string {
    $q = mb_substr(trim((string)($_GET['q'] ?? '')), 0, 80);
    $like = '%' . addcslashes($q, '%_\\') . '%';
    $users = all('SELECT id,username,name,phone,role,created_at,last_login_at,vip_until FROM users WHERE (? = \'\' OR username LIKE ? OR name LIKE ?) ORDER BY created_at DESC LIMIT 500', [$q, $like, $like]);
    $total = (int)scalar('SELECT COUNT(*) FROM users');
    $vips = (int)scalar('SELECT COUNT(*) FROM users WHERE vip_until > UTC_TIMESTAMP()');
    $visits = (int)scalar('SELECT COUNT(*) FROM visitor_events WHERE visited_at >= UTC_DATE()');
    $rows = '';
    foreach ($users as $u) {
        $active = $u['vip_until'] !== null && strtotime($u['vip_until'] . ' UTC') > time();
        $until = $active ? (new DateTimeImmutable($u['vip_until'], new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Africa/Cairo'))->format('Y-m-d') : '';
        $label = $active ? 'VIP حتى ' . escape($until) : 'غير مفعّل';
        $action = $u['role'] === 'admin' ? '—' : '<form method="post" action="/admin"><input type="hidden" name="user_id" value="' . escape($u['id']) . '"><input type="date" name="vip_until" aria-label="تاريخ انتهاء VIP" value="' . escape($until) . '"><button type="submit">' . ($active ? 'تحديث VIP' : 'تفعيل VIP') . '</button></form>';
        $rows .= '<tr><td><b>' . escape($u['username']) . '</b><br><span class="muted">' . escape($u['name']) . ($u['role'] === 'admin' ? ' · مدير' : '') . '</span></td><td>' . escape($u['phone'] ?: '—') . '</td><td>' . escape($u['created_at']) . '</td><td>' . escape($u['last_login_at'] ?: '—') . '</td><td class="' . ($active ? 'vip' : 'off') . '">' . $label . '</td><td class="actions">' . $action . '</td></tr>';
    }
    $body = '<section class="top"><div><h1>إدارة الحسابات</h1><div class="muted">أهلًا ' . escape($admin['username']) . ' · بيانات الحسابات وإدارة VIP</div></div><form class="logout-form" method="post" action="/logout"><input type="hidden" name="csrf" value="' . escape($admin['csrf_token']) . '"><button type="submit">تسجيل الخروج</button></form></section>' . ($notice ? '<p class="note">' . escape($notice) . '</p>' : '') . '<section class="card"><div class="stats"><div class="stat"><b>' . $total . '</b>إجمالي الحسابات</div><div class="stat"><b>' . $vips . '</b>حساب VIP نشط</div><div class="stat"><b>' . $visits . '</b>زيارات الموقع اليوم</div></div></section><section class="card"><form class="search" method="get" action="/admin"><input type="search" name="q" value="' . escape($q) . '" placeholder="ابحث باسم المستخدم أو الاسم"><button>بحث</button></form></section><section class="card table-wrap"><table><thead><tr><th>الحساب</th><th>الهاتف</th><th>تاريخ الإنشاء</th><th>آخر دخول</th><th>VIP</th><th>إدارة VIP</th></tr></thead><tbody>' . ($rows ?: '<tr><td colspan="6">لا توجد حسابات مطابقة.</td></tr>') . '</tbody></table></section>';
    return '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="' . escape($admin['csrf_token']) . '"><title>إدارة أثر</title><style>:root{font-family:system-ui,"Segoe UI",sans-serif;color:#17202a;background:#f3f6f5}*{box-sizing:border-box}body{margin:0;padding:24px}.wrap{max-width:1120px;margin:auto}.top,.card{background:white;border:1px solid #e2e8e6;border-radius:16px;padding:20px;margin-bottom:16px}.top{display:flex;align-items:center;justify-content:space-between;gap:14px}.stats{display:flex;gap:12px;flex-wrap:wrap}.stat{background:#f4f8f7;padding:12px 18px;border-radius:12px}.stat b{display:block;font-size:1.3rem}form.search{display:flex;gap:8px}input,button{font:inherit;padding:9px 12px;border:1px solid #cbd5d1;border-radius:9px}button{background:#166b57;color:white;border:0;cursor:pointer}table{width:100%;border-collapse:collapse;background:white}th,td{text-align:right;padding:11px;border-bottom:1px solid #edf0ef}th{background:#f6f8f7}.table-wrap{overflow:auto}.muted{color:#66736e}.vip{color:#08734f;font-weight:700}.off{color:#8b9290}.note{padding:12px;border-radius:10px;background:#eaf7ef;margin-bottom:12px}.actions{min-width:220px}.actions form{display:flex;gap:6px;align-items:center}.actions input{max-width:155px}.logout-form{margin:0}.logout-form button{background:#fff;color:#8b3b2e;border:1px solid #dfb4a8}h1{margin:0 0 6px}@media(max-width:650px){body{padding:10px}.top{align-items:flex-start;flex-direction:column}th,td{padding:8px}}</style></head><body><main class="wrap">' . $body . '</main><script>document.addEventListener("submit",async e=>{const f=e.target;if(f.method.toLowerCase()!=="post")return;e.preventDefault();const r=await fetch(f.action,{method:"POST",headers:{"X-CSRF-Token":document.querySelector("meta[name=csrf-token]").content,"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams(new FormData(f))});if(new URL(f.action).pathname==="/logout"){if(r.ok)location.assign("/login");return}document.open();document.write(await r.text());document.close()});</script></body></html>';
}

function import_page(array $user): string {
    return '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="' . escape($user['csrf_token']) . '"><title>استيراد بيانات أثر</title><style>body{font-family:system-ui,sans-serif;direction:rtl;background:#f8f4e7;color:#173d35;margin:0;padding:24px}.box{max-width:600px;margin:7vh auto;background:white;border:1px solid #d8bf78;border-radius:18px;padding:24px;box-shadow:0 12px 30px #14372b22}h1{margin-top:0}p{line-height:1.8}input{display:block;margin:20px 0}button{background:#0a6b56;color:white;border:0;border-radius:10px;padding:12px 22px;font:inherit;cursor:pointer}a{color:#0a6b56}#status{font-weight:700}</style></head><body><main class="box"><a href="/">العودة للموقع</a><h1>استيراد بياناتك القديمة</h1><p>اختر ملف JSON الذي نزلته من حسابك في النسخة القديمة. سيُستبدل جدول هذا الحساب وإعداداته بما في الملف. احتفظ بنسخة من بياناتك الحالية أولًا من <a href="/api/export">تنزيل نسخة احتياطية</a>.</p><input id="backup" type="file" accept=".json,application/json"><button id="import" type="button">استيراد البيانات</button><p id="status" role="status"></p></main><script>document.getElementById("import").onclick=async()=>{const f=document.getElementById("backup").files[0],s=document.getElementById("status");if(!f){s.textContent="اختر ملف JSON أولًا.";return}if(f.size>8*1024*1024){s.textContent="الملف أكبر من المسموح.";return}s.textContent="جارٍ الاستيراد…";try{const r=await fetch("/api/import",{method:"POST",headers:{"Content-Type":"application/json","X-CSRF-Token":document.querySelector("meta[name=csrf-token]").content},body:await f.text()});const d=await r.json();s.textContent=d.ok?"تم استيراد البيانات. افتح الصفحة الرئيسية لرؤية جدولك.":d.error||"تعذر الاستيراد."}catch{s.textContent="تعذر الاتصال بالسيرفر."}};</script></body></html>';
}
